import { EquipGroup, useEquipGroupingStore } from "../../../hooks/useEquipGroupingStore";
import { simpleHover, useHoverStore } from "../../../hooks/useHoverStore";
import { usePaletStore } from "../../../hooks/usePaletStore";
import { processSelect, useUnitInteractionStore } from "../../../hooks/useUnitInteractionsStore";
import { useUnitStore } from "../../../hooks/useUnitStore";
import { getGroupFromSingleItem } from "../../../logic/Items/itemListing";
import { EquipmentTable, RawUnit } from "../../../logic/Units/logic";
import { SafeNumberInput } from "../EditorElements/SafeNumberInput";

export default function RawUnitEditorSegment() {
  const { unitMap, trueRootId } = useUnitStore(s => s)
  const selectedId = processSelect(useUnitInteractionStore(s => s.selectSignature), unitMap, trueRootId) as string
  const updateUnit = useUnitStore((s) => s.updateUnit);
  const splitUnit = useUnitStore(s => s.splitRawUnit)
  const { addUnitToPalet } = usePaletStore(s => s)
  const { groups: eqGroups } = useEquipGroupingStore(s => s)
  const { callSimpleI, callOff } = useHoverStore(s => s)

  const unit = unitMap[selectedId] as RawUnit

  if (!unit || unit.type !== "raw") {
    throw Error(`Unit ID or type wrong ID = ${selectedId}, type = ${unit?.type}`)
  }

  const equipmentEntries = Object.entries(unit.equipment);

  const changeEquipment = (additionalEq: EquipmentTable) => {
    const newEquipment = { ...unit.equipment, ...additionalEq};
    updateUnit(selectedId, { ...unit, equipment: newEquipment });
  };

  const deleteEquipment = (type: string) => {
    const newEquipment = { ...unit.equipment };
    delete newEquipment[type];
    updateUnit(selectedId, { ...unit, equipment: newEquipment });
  };

  const handleAdding = () => {
    const p = "Enter new equipment type. Press double space to enter quantity (e.g. 'Rifle  30', 'Howitzer', 'MG42  6' , Stryker IFV  14 ). Enter commas (,) to add new type:"
    const inp = prompt(p);
    if (!inp) return;

    let eq: EquipmentTable = {}
    const pairs = inp.split(/\s*,\s*/) // Splits if theres comma between
    for (const pair of pairs) {
      const [left, right] = pair.split(/ {2,}/); // Split by double space or more
      const type = left.trim()
      const qty = parseInt(right, 10);
  
      if (!isNaN(qty)) {
        eq[type] = qty;
      } else {
        const qtyPrompt = prompt(`Enter quantity for "${type}":`);
        if (qtyPrompt && !isNaN(parseInt(qtyPrompt, 10))) {
          eq[type] = parseInt(qtyPrompt, 10);
        }
      }
    }

    changeEquipment(eq)
  };

  const handleSpliting = () => {
    const p = "Split unit into how many children? (enter not a number to cancel) : "
    const userInput = prompt(p)
    if (!userInput)
      return

    const childCount = parseInt(userInput, 10)
    if (isNaN(childCount)) {
      return
    }

    splitUnit(selectedId, childCount, addUnitToPalet)
  }

  return (
    <div className="editor-segment-flex">
      <div className="editor-segment-row">
        <span className="text-lg font-bold">Equipment</span>
        <button onClick={handleAdding} className="btn-emoji">
          ➕Add
        </button>
        <button onClick={handleSpliting} className="btn-emoji">
          ➗Split
        </button>
      </div>

      {equipmentEntries.map(([type, value]) => 
        equimentEntry(type, value, eqGroups, changeEquipment, deleteEquipment, callSimpleI, callOff)
      )}
    </div> )
}

function equimentEntry(
  type: string, amount: number, eqGroups: EquipGroup[], 
  changeEquipment: (additionalEq: EquipmentTable) => void, deleteEquipment: (type: string) => void,
  callSimpleI: (n: simpleHover) => void, callOff: () => void
) {
  const eqGroup = getGroupFromSingleItem(eqGroups, type);
  const style = eqGroup ? {color: eqGroup.color} : undefined;
  const onHover = () => eqGroup 
          ? callSimpleI({header: `${eqGroup.name}/${type}`, desc: "This item belongs to the Equipment Group (🗡️) '" + eqGroup.name + "'"}) 
          : callSimpleI("This item doesn't belong to any Equipment Group (🗡️)")

  return (
    <div key={type} className="editor-segment-row" 
      style={style}
      onMouseEnter={onHover}
      onMouseLeave={callOff}
    >
      <span className="w-24"><b>{type}</b></span>
      <SafeNumberInput
        id={type}
        count={amount}
        onCountChange={nc => changeEquipment({[type]: nc})}
        className="!w-24"
      />
      <button onClick={() => deleteEquipment(type)} className="btn-emoji !p-0">
        ❌
      </button>
    </div>)
}